52	import org.springframework.security.access.prepost.PreAuthorize;
53	import org.springframework.web.bind.annotation.CrossOrigin;
54	import org.springframework.web.bind.annotation.RequestMapping;
55	import org.springframework.web.bind.annotation.RestController;
56	import org.springframework.web.util.UriComponentsBuilder;
57	
58	import jakarta.transaction.Transactional;
59	
60	/**
61	 * @author Vitaliy Fedoriv
62	 */
63	
64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    /** Maximum number of owners a single city may contain; creating an owner in a city that
70	     *  already has this many owners is rejected with 409 Conflict. */
71	    private static final int MAX_OWNERS_PER_CITY = 50;
72	
73	    /** Maximum number of owners that may be created on a single day (by registration date); creating
74	     *  an owner once this many owners already carry today's registration date is rejected with
75	     *  429 Too Many Requests. */
76	    private static final int MAX_OWNERS_PER_DAY = 100;
77	
78	    /** When more than this many owners already carry today's registration date at creation time, the
79	     *  new owner's 'bulkSignupWarning' flag is set true; otherwise it is false. */
80	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
81	
82	    /** Dedicated audit logger; a line is emitted here for each successful owner create. */
83	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
84	
85	    private final ClinicService clinicService;
86	
87	    private final OwnerMapper ownerMapper;
88	
89	    private final PetMapper petMapper;
90	
91	    private final VisitMapper visitMapper;
92	
93	    private final TelephoneNormalizer telephoneNormalizer;
94	
95	    private final HouseholdNormalizer householdNormalizer;
96	
97	    private final AddressNormalizer addressNormalizer;
98	
99	    public OwnerRestControllerV1(ClinicService clinicService,
100	                                 OwnerMapper ownerMapper,
101	                                 PetMapper petMapper,
102	                                 VisitMapper visitMapper,
103	                                 TelephoneNormalizer telephoneNormalizer,
104	                                 HouseholdNormalizer householdNormalizer,
105	                                 AddressNormalizer addressNormalizer) {
106	        this.clinicService = clinicService;
107	        this.ownerMapper = ownerMapper;
108	        this.petMapper = petMapper;
109	        this.visitMapper = visitMapper;
110	        this.telephoneNormalizer = telephoneNormalizer;
111	        this.householdNormalizer = householdNormalizer;
112	        this.addressNormalizer = addressNormalizer;
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
118	        Collection<Owner> owners;
119	        if (lastName != null) {
120	            owners = this.clinicService.findOwnerByLastName(lastName);
121	        } else {
122	            owners = this.clinicService.findAllOwners();
123	        }
124	        if (owners.isEmpty()) {
125	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
126	        }
127	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
133	        Owner owner = this.clinicService.findOwnerById(ownerId);
134	        if (owner == null) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
143	        HttpHeaders headers = new HttpHeaders();
144	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
145	        normalizeOwnerFields(owner);
146	        // Enforce the pre-persistence policies that can reject the new owner outright.
147	        rejectDisallowedOwnerCreation(owner);
148	        // Resolve the owner's household membership: assign the shared 'householdId' when the
149	        // request opts in and joins an existing household, and record the household size. This runs
150	        // before the identity-key check so that check sees the owner's final household id.
151	        applyHouseholdMembership(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
152	        // Reject the create when the owner's whole derived identity key (normalized telephone,
153	        // email and household id) already matches an existing owner. This single rule subsumes the
154	        // former separate telephone, email and household duplicate checks.
155	        rejectWhenIdentityInUse(owner);
156	        // Assign the remaining create-time derived fields (namesake count, customer code,
157	        // membership number and bulk-signup warning), each fixed at creation time.
158	        assignDerivedFields(owner);
159	        this.clinicService.saveOwner(owner);
160	        // Emit an audit line for the successful create, carrying the owner id, customer code and
161	        // registration date so the create can be traced from the dedicated AUDIT log.
162	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
163	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
164	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
165	        headers.setLocation(UriComponentsBuilder.newInstance()
166	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
167	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
168	    }
169	
170	    /**
171	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
172	     * outright, in order, before any derived fields are assigned or the owner is saved. Each
173	     * independent rule lives in its own {@code rejectWhen...} guard and is applied here in order, so
174	     * the sequence of create-time rejections stays readable and a new rule is added as one more
175	     * guard. Grouping the rules here keeps {@link #addOwner} focused on the household, derived-field
176	     * and persistence steps. The single duplicate rule that rejects an owner whose whole identity
177	     * key matches an existing one is applied separately in {@link #rejectWhenIdentityInUse}, after
178	     * the household id has been resolved, because that key includes the household id.
179	     *
180	     * @param owner the newly mapped and normalized owner being created
181	     */
182	    private void rejectDisallowedOwnerCreation(Owner owner) {
183	        rejectWhenDailyLimitReached(owner);
184	        rejectWhenCityAtCapacity(owner);
185	    }
186	
187	    /**
188	     * Applies the household-membership rules for a newly normalized owner being created. It finds
189	     * the existing owners who share the owner's household (same last name and address, compared
190	     * case-insensitively with collapsed whitespace), then, using that single lookup: when the
191	     * request opts in via {@code sharesHousehold} and the owner joins an existing household, assigns
192	     * the new owner and every existing member the same stable {@code householdId}; and records the
193	     * owner's {@code householdSize}. Sharing a household is no longer a rejection on its own: a new
194	     * owner is rejected only when its whole identity key matches an existing owner (see
195	     * {@link #rejectWhenIdentityInUse}), and the household id resolved here is part of that key.
196	     *
197	     * @param owner           the newly mapped and normalized owner being created
198	     * @param sharesHousehold whether the request opted in to joining an existing household
199	     */
200	    private void applyHouseholdMembership(Owner owner, boolean sharesHousehold) {
201	        // Identify any existing owners who share a household (same last name and address,
202	        // compared case-insensitively with collapsed whitespace) with the owner being created.
203	        List<Owner> householdMembers = sameHouseholdOwners(owner.getLastName(), owner.getAddress());
204	        // When opting in and joining an existing household, assign the new owner and every
205	        // existing member the same stable household identifier derived from the last name and
206	        // address, so all owners of the household share one 'householdId'.
207	        if (sharesHousehold && !householdMembers.isEmpty()) {
208	            String householdId = householdNormalizer.householdId(owner.getLastName(), owner.getAddress());
209	            owner.setHouseholdId(householdId);
210	            for (Owner member : householdMembers) {
211	                if (!householdId.equals(member.getHouseholdId())) {
212	                    member.setHouseholdId(householdId);
213	                    this.clinicService.saveOwner(member);
214	                }
215	            }
216	        }
217	        // Record the size of this owner's household after this create, i.e. the number of owners
218	        // sharing this owner's 'householdId' once it is persisted. An owner that shares an existing
219	        // household counts the matched members plus itself; an owner without a shared household is a
220	        // household of one. Fixed at creation time.
221	        owner.setHouseholdSize(owner.getHouseholdId() == null ? 1 : householdMembers.size() + 1);
222	    }
223	
224	    /**
225	     * Assigns the create-time derived fields of a newly normalized owner whose household membership
226	     * has already been resolved: the namesake count, the per-city customer code, the membership
227	     * number derived from that customer code and the registration year, and the bulk-signup warning
228	     * flag. Each value is fixed at creation time and is independent of the others. Grouping them
229	     * here keeps {@link #addOwner} focused on the high-level create sequence.
230	     *
231	     * @param owner the owner being created, already normalized and with its household resolved
232	     */
233	    private void assignDerivedFields(Owner owner) {
234	        // Record how many existing owners already share this owner's first and last name
235	        // (compared case-insensitively) before this create, fixed at creation time.
236	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
237	        // Assign the customer code '<REGION>-<HASH8>' from the region derived from the postcode
238	        // and an 8-hex-character hash of the normalized telephone and last name, fixed at creation
239	        // time.
240	        owner.setCustomerCode(customerCode(owner));
241	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
242	        // of the registration date's year (e.g. 'NSW-A1B2C3D4-M26'), fixed at creation time.
243	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
244	        // Flag the create when more than 80 owners have already been created on this owner's
245	        // (adjusted business-day) registration date, fixed at creation time.
246	        owner.setBulkSignupWarning(
247	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
248	    }
249	
250	    /**
251	     * Rejects creating an owner whose whole derived identity key already matches an existing owner,
252	     * with 409 Conflict. The identity key ({@link Owner#getIdentityKey()}) joins the normalized
253	     * telephone, the email (or empty) and the household id (or empty), so this single rule replaces
254	     * the former separate telephone, email and household duplicate checks: two owners collide only
255	     * when their whole keys are equal, and members of one household with different telephones have
256	     * different keys and are both allowed.
257	     *
258	     * @param owner the owner being created, already normalized and with its household resolved
259	     */
260	    private void rejectWhenIdentityInUse(Owner owner) {
261	        String identityKey = owner.getIdentityKey();
262	        boolean inUse = existingOwners()
263	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
264	        if (inUse) {
265	            throw new DuplicateIdentityException(
266	                "An owner with identity key " + identityKey + " already exists");
267	        }
268	    }
269	
270	    /**
271	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners already carry this
272	     * owner's adjusted business-day registration date, with 429 Too Many Requests.
273	     *
274	     * @param owner the owner being created
275	     */
276	    private void rejectWhenDailyLimitReached(Owner owner) {
277	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
278	            throw new DailyOwnerLimitExceededException(
279	                "The maximum number of owners that may be created today has already been reached");
280	        }
281	    }
282	
283	    /**
284	     * Rejects creating an owner when the owner's city already contains {@link #MAX_OWNERS_PER_CITY}
285	     * or more owners, with 409 Conflict.
286	     *
287	     * @param owner the owner being created
288	     */
289	    private void rejectWhenCityAtCapacity(Owner owner) {
290	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
291	            throw new CityCapacityExceededException(
292	                "The city " + owner.getCity() + " already contains the maximum number of owners");
293	        }
294	    }
295	
296	    /**
297	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
298	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
299	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
300	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
301	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
302	     * server's current date. Canonicalising the address here, before the household checks read it,
303	     * ensures duplicate detection and the shared household id both compare the normalized form.
304	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
305	     * duplicate, household and customer-code rules.
306	     *
307	     * @param owner the newly mapped owner to canonicalize
308	     */
309	    private void normalizeOwnerFields(Owner owner) {
310	        // Normalize the address on create so it is stored and returned in canonical form and every
311	        // later comparison (household duplicate detection and the shared household id) uses it.
312	        // A value that is blank after normalization is rejected with 400.
313	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
314	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
315	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
316	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
317	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
318	        // Store the (already syntactically validated) email lower-cased so it is persisted and
319	        // returned in canonical form. A missing email is left untouched.
320	        owner.setEmail(normalizeEmail(owner.getEmail()));
321	        // Validate the optional postcode against the fixed range for the city's region. A postcode
322	        // is checked only when present (it is optional); one out of range for the city's region is
323	        // rejected with 400. A city with no known region accepts any 4-digit postcode. The stored
324	        // value is left unchanged.
325	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
326	        // Reject a supplied registration date that is later than the server's current date with
327	        // 400, before any defaulting or business-day adjustment, so a future date is never
328	        // persisted regardless of how the roll-forward would move it.
329	        rejectFutureRegistrationDate(owner.getRegistrationDate());
330	        // Default the registration date to the server's current date when the client did not
331	        // supply one, then roll the effective date forward to a business day so a Saturday or
332	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
333	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
334	        // date-derived field (such as the membership number's year segment) and the per-day
335	        // create-limit are computed from.
336	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
337	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
338	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
339	    }
340	
341	    /**
342	     * Rejects a supplied registration date that is later than the server's current date with a
343	     * 400 Bad Request. A missing registration date (defaulted to the server date later) is
344	     * accepted, and a date on or before today is left for the normal defaulting and business-day
345	     * adjustment.
346	     *
347	     * @param registrationDate the client-supplied registration date, or {@code null} when absent
348	     */
349	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
350	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
351	            throw new InvalidRegistrationDateException(
352	                "The supplied registration date " + registrationDate + " is later than the current date");
353	        }
354	    }
355	
356	    /**
357	     * Rolls a registration date forward to a business day: a Saturday or Sunday advances to the
358	     * following Monday, while a weekday is returned unchanged. Applied to the effective
359	     * registration date (whether supplied in the request or defaulted to the server date) so the
360	     * persisted registration date, every value derived from it and the per-day create-limit all
361	     * use the adjusted business day.
362	     *
363	     * @param date the effective registration date
364	     * @return the same date if it is a weekday, otherwise the following Monday
365	     */
366	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
367	        java.time.LocalDate adjusted = date;
368	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
369	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
370	            adjusted = adjusted.plusDays(1);
371	        }
372	        return adjusted;
373	    }
374	
375	    /**
376	     * Lower-cases the supplied email address so it is stored and returned in canonical form.
377	     * Bean validation on the request DTO has already guaranteed that any non-null value is a
378	     * syntactically valid address (rejecting anything else with 400).
379	     *
380	     * @param email the email value (may be {@code null})
381	     * @return the lower-cased email, or {@code null} if the input was {@code null}
382	     */
383	    private String normalizeEmail(String email) {
384	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
385	    }
386	
387	    /**
388	     * Builds the customer code '<REGION>-<HASH8>' for a newly created owner, where REGION is the
389	     * region derived from the owner's postcode (falling back to the city, via
390	     * {@link LocalityResolver}) and HASH8 is the first 8 upper-case hex characters of the SHA-256
391	     * digest over the owner's normalized telephone concatenated with the last name (e.g.
392	     * 'NSW-A1B2C3D4'). The identity carries no sequence number, so it is a pure function of the
393	     * owner's region and identity fields.
394	     *
395	     * @param owner the owner being created, already normalized
396	     * @return the formatted customer code
397	     */
398	    private String customerCode(Owner owner) {
399	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
400	        String hash8 = Sha256Hex.upperHexPrefix(owner.getTelephone() + owner.getLastName(), 8);
401	        return region + "-" + hash8;
402	    }
403	
404	    /**
405	     * Streams the existing owners that the create-time rules match a new owner against. Every
406	     * duplicate, quota and derived-field rule scans this same set of owners and differs only in the
407	     * predicate it applies, so fetching them is centralized here to keep each rule focused on its
408	     * own matching criterion rather than on how the existing owners are retrieved.
409	     *
410	     * @return a stream over all existing owners
411	     */
412	    private Stream<Owner> existingOwners() {
413	        return this.clinicService.findAllOwners().stream();
414	    }
415	
416	    /**
417	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
418	     * fix the per-city sequence of an owner's customer code at creation time.
419	     *
420	     * @param city the city of the owner being created
421	     * @return the number of existing owners in a matching city
422	     */
423	    private int countOwnersInCity(String city) {
424	        return (int) existingOwners()
425	            .filter(existing -> existing.getCity() != null
426	                && existing.getCity().equalsIgnoreCase(city))
427	            .count();
428	    }
429	
430	    /**
431	     * Counts the existing owners whose registration date is the given adjusted business day. Used
432	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
433	     * owners already carry that business day as their registration date.
434	     *
435	     * @param date the adjusted business-day registration date to match
436	     * @return the number of existing owners registered on that date
437	     */
438	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
439	        return (int) existingOwners()
440	            .filter(existing -> date.equals(existing.getRegistrationDate()))
441	            .count();
442	    }
443	
444	    /**
445	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
446	     * the last two digits of the registration date's year (e.g. 'NSW-A1B2C3D4-M26').
447	     *
448	     * @param customerCode     the owner's customer code
449	     * @param registrationDate the owner's registration date
450	     * @return the formatted membership number
451	     */
452	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
453	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
454	    }
455	
456	    /**
457	     * Returns the existing owners who share the given household, i.e. have the same last name and
458	     * the same address. The comparison delegates to {@link HouseholdNormalizer} so that values
459	     * differing only in letter case or in incidental whitespace are treated as the same household.
460	     *
461	     * @param lastName the last name of the owner being created
462	     * @param address  the address of the owner being created
463	     * @return the existing owners with a matching last name and address (possibly empty)
464	     */
465	    private List<Owner> sameHouseholdOwners(String lastName, String address) {
466	        String householdKey = householdNormalizer.householdKey(lastName, address);
467	        return existingOwners()
468	            .filter(existing -> householdNormalizer
469	                .householdKey(existing.getLastName(), existing.getAddress()).equals(householdKey))
470	            .toList();
471	    }
472	
473	    /**
474	     * Counts the existing owners who share the given first and last name, compared
475	     * case-insensitively. Used to fix an owner's namesake count at creation time.
476	     *
477	     * @param firstName the first name of the owner being created
478	     * @param lastName  the last name of the owner being created
479	     * @return the number of existing owners with a matching first and last name
480	     */
481	    private int countNamesakes(String firstName, String lastName) {
482	        return (int) existingOwners()
483	            .filter(existing -> existing.getFirstName() != null
484	                && existing.getFirstName().equalsIgnoreCase(firstName)
485	                && existing.getLastName() != null
486	                && existing.getLastName().equalsIgnoreCase(lastName))
487	            .count();
488	    }
489	
490	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
491	    @Override
492	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
493	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
494	        if (currentOwner == null) {
495	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
496	        }
497	        currentOwner.setAddress(ownerFieldsDto.getAddress());
498	        currentOwner.setCity(ownerFieldsDto.getCity());
499	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
500	        currentOwner.setLastName(ownerFieldsDto.getLastName());
501	        // Normalize the telephone to canonical E.164 form so it is stored and returned
502	        // consistently with create; an unformattable value is rejected with 400.
503	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
504	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
505	        this.clinicService.saveOwner(currentOwner);
506	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
507	    }
508	
509	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
510	    @Transactional
511	    @Override
512	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
513	        Owner owner = this.clinicService.findOwnerById(ownerId);
514	        if (owner == null) {
515	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
516	        }
517	        this.clinicService.deleteOwner(owner);
518	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
519	    }
520	
521	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
522	    @Override
523	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
524	        Owner owner = this.clinicService.findOwnerById(ownerId);
525	        if (owner == null) {
526	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
527	        }
528	        HttpHeaders headers = new HttpHeaders();
529	        Pet pet = petMapper.toPet(petFieldsDto);
530	        owner.setId(ownerId);
531	        pet.setOwner(owner);
532	        pet.getType().setName(null);
533	        this.clinicService.savePet(pet);
534	        PetDto petDto = petMapper.toPetDto(pet);
535	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
536	            .buildAndExpand(pet.getId()).toUri());
537	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
538	    }
539	
540	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
541	    @Override
542	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
543	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
544	        if (currentOwner != null) {
545	            Pet currentPet = this.clinicService.findPetById(petId);
546	            if (currentPet != null) {
547	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
548	                currentPet.setName(petFieldsDto.getName());
549	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
550	                this.clinicService.savePet(currentPet);
551	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
552	            }
553	        }
554	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
555	    }
556	
557	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
558	    @Override
559	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
560	        HttpHeaders headers = new HttpHeaders();
561	        Visit visit = visitMapper.toVisit(visitFieldsDto);
562	        Pet pet = new Pet();
563	        pet.setId(petId);
564	        visit.setPet(pet);
565	        this.clinicService.saveVisit(visit);
566	        VisitDto visitDto = visitMapper.toVisitDto(visit);
567	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
568	            .buildAndExpand(visit.getId()).toUri());
569	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
570	    }
571	
572	
573	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
574	    @Override
575	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
576	        Owner owner = this.clinicService.findOwnerById(ownerId);
577	        if (owner != null) {
578	            Pet pet = owner.getPet(petId);
579	            if (pet != null) {
580	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
581	            }
582	        }
583	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
584	    }
585	}
